#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace IslandSystem {
public class LocomotionReview:MonoBehaviour {
 readonly List<string> report=new List<string>();ActionMotor motor;Mesh baked;float minimumSole=100,minimumRoot=100,peak;
 void Check(bool good,string text){report.Add((good?"PASS ":"FAIL ")+text);File.WriteAllLines("Logs/LocomotionReview.txt",report);if(!good)throw new Exception(text);}
 IEnumerator Start(){yield return new WaitForSeconds(.5f);motor=FindAnyObjectByType<ActionMotor>();motor.animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;foreach(var w in FindObjectsByType<Workbench>())w.enabled=false;baked=new Mesh();float until=Time.realtimeSinceStartup+4;while(!motor.Grounded&&Time.realtimeSinceStartup<until)yield return null;
  motor.Teleport(motor.Spawn+Vector3.right*1.8f);yield return new WaitForSeconds(.3f);motor.Yaw=0;motor.ReviewSprint=true;
  bool jumpShot=false;float start=Time.time;var poses=new List<Quaternion>();while(Time.time-start<4){motor.ReviewAxes=(Time.time-start)%1<.5f?Vector2.right:Vector2.left;poses.Add(motor.animator.GetBoneTransform(HumanBodyBones.LeftLowerLeg).localRotation);yield return new WaitForSeconds(.04f);}
  try{var run=motor.animator.GetCurrentAnimatorStateInfo(0);Check(run.IsName("Run")&&run.loop&&run.normalizedTime>4,"Sprint remains in looping Run after 4 seconds; normalizedTime="+run.normalizedTime);var late=poses.Skip(poses.Count/2).ToArray();float variation=late.Max(p=>Quaternion.Angle(late[0],p));Shot("06-Sprint-Loop");Check(variation>3,"Leg pose continues changing after multiple sprint cycles; degrees="+variation);Shot("06-Sprint-Loop");}catch(Exception e){Fail(e);yield break;}
  motor.ReviewAxes=Vector2.zero;motor.ReviewSprint=false;yield return new WaitForSeconds(.3f);int jumps=motor.Jumps,landings=motor.Landings;
  for(int i=0;i<6;i++){motor.Teleport(motor.Spawn+Vector3.right*(i%3));yield return new WaitForSeconds(.25f);until=Time.time+3;while(!motor.Grounded&&Time.time<until)yield return null;try{Check(motor.Jump(),"Jump "+(i+1)+" accepted from ground");}catch(Exception e){Fail(e);yield break;}until=Time.time+3;while(!motor.Grounded&&Time.time<until){Sample();if(!jumpShot&&motor.transform.position.y-motor.Spawn.y>.8f){Shot("07-Jump-Clearance");jumpShot=true;}yield return new WaitForSeconds(.025f);}for(int j=0;j<14;j++){Sample();yield return new WaitForSeconds(.025f);}}
  try{Check(motor.Jumps-jumps==6&&motor.Landings-landings==6,"Six jumps each return to a real CharacterController ground contact");Check(peak>.8f,"Jump physically rises above ground; peak="+peak);Check(minimumRoot>=-.04f,"Controller origin never crosses ground; minimum clearance="+minimumRoot);Check(minimumSole>=-.08f,"Rendered character sole never sinks through ground, including landing blend; minimum clearance="+minimumSole);Shot("08-Landing-Clearance");Directory.CreateDirectory("Docs/IslandSystem/ActionTrial");File.WriteAllLines("Docs/IslandSystem/ActionTrial/LocomotionReview.txt",report);Destroy(baked);EditorApplication.isPlaying=false;}catch(Exception e){Fail(e);}
 }
 void Sample(){float floor=float.NegativeInfinity;foreach(var h in Physics.RaycastAll(new Vector3(motor.transform.position.x,motor.Spawn.y+6,motor.transform.position.z),Vector3.down,12))if(!h.collider.transform.IsChildOf(motor.transform)&&!h.collider.isTrigger&&h.point.y>floor)floor=h.point.y;if(float.IsNegativeInfinity(floor))throw new Exception("Missing ground collider");minimumRoot=Mathf.Min(minimumRoot,motor.transform.position.y-floor);peak=Mathf.Max(peak,motor.transform.position.y-floor);foreach(var renderer in motor.GetComponentsInChildren<SkinnedMeshRenderer>()){renderer.BakeMesh(baked);float sole=float.PositiveInfinity;foreach(var vertex in baked.vertices)sole=Mathf.Min(sole,renderer.transform.TransformPoint(vertex).y);minimumSole=Mathf.Min(minimumSole,sole-floor);}}
 void Shot(string name){Directory.CreateDirectory("Docs/IslandSystem/ActionTrial");var cam=motor.view;var rt=new RenderTexture(1280,720,24);var old=cam.targetTexture;var active=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes("Docs/IslandSystem/ActionTrial/"+name+".png",image.EncodeToPNG());cam.targetTexture=old;RenderTexture.active=active;Destroy(rt);Destroy(image);}
 void Fail(Exception e){UnityEngine.Debug.LogException(e);EditorApplication.Exit(2);}
}
[InitializeOnLoad]public static class LocomotionReviewEntry {
 static LocomotionReviewEntry(){if(SessionState.GetBool("LocomotionReview",false))EditorApplication.playModeStateChanged+=Attach;}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity");SessionState.SetBool("LocomotionReview",true);EditorApplication.playModeStateChanged+=Attach;EditorApplication.isPlaying=true;}
 static void Attach(PlayModeStateChange s){if(s==PlayModeStateChange.EnteredPlayMode)new GameObject("Background locomotion regression").AddComponent<LocomotionReview>();if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("LocomotionReview",false);EditorApplication.Exit(0);}}
}
}
#endif
